  --color-success-fg: #75D39A;
  --color-warning-bg: #42341F;
  --color-warning-fg: #E8B966;
  --color-error-bg:   #472B27;
  --color-error-fg:   #E99980;
  --color-info-bg:    #0E353B;
  --color-info-fg:    #72D2DD;

  /* Surface */
  --bg-base:     #13343B;
  --bg-subtle:   #102C32;
  --bg-elevated: #183F47;
  --bg-overlay:  rgba(5,19,23,0.68);

  /* Text */
  --text-primary:    #F3F3EE;
  --text-secondary:  #C9D8D9;
  --text-tertiary:   #A9C1C5;
  --text-on-primary: #0B2025;
  --text-disabled:   #557076;

  /* Border */
  --border-default: #28545C;
  --border-subtle:  #1E464D;
  --border-strong:  #37666E;
  --border-focus:   #1FB8CD;
}

